(async () => {
  if (!window.__seeded) { window.__seeded = true; Sample.install(); }
  App.show('places');
  document.getElementById('toast').hidden = true;
  await new Promise(r => setTimeout(r, 500));
})()

(async () => {
  App.openPlace('smp-orangery');
  await new Promise(r => setTimeout(r, 600));
  document.getElementById('placeBody').scrollTop = 0;
  document.getElementById('toast').hidden = true;
})()

(async () => {
  App.openPlace('smp-ledger');
  await new Promise(r => setTimeout(r, 600));
  const body = document.getElementById('placeBody');
  const cards = [...body.querySelectorAll('.card')];
  const entrance = cards.find(c => c.querySelector('h3') && c.querySelector('h3').textContent === 'The way in');
  body.scrollTop = entrance.offsetTop - 8;
  document.getElementById('toast').hidden = true;
  await new Promise(r => setTimeout(r, 400));
})()

(async () => {
  App.back();
  await new Promise(r => setTimeout(r, 300));
  App.startSurvey(null, null);
  await new Promise(r => setTimeout(r, 400));
  const n = document.getElementById('npName');
  n.value = 'Quayside Bookshop'; n.dispatchEvent(new Event('input', { bubbles: true }));
  [...document.querySelectorAll('#surveyBody .chip')].find(c => c.textContent === 'Shop').click();
  await new Promise(r => setTimeout(r, 250));
  const a = document.getElementById('npArea');
  a.value = 'Quay Lane'; a.dispatchEvent(new Event('input', { bubbles: true }));
  document.getElementById('surveyNext').click();
  await new Promise(r => setTimeout(r, 350));
  const pick = (q, label) => {
    const box = [...document.querySelectorAll('#surveyBody .q')].find(x => x.querySelector('.q-h').textContent.indexOf(q) >= 0);
    if (box) { const c = [...box.querySelectorAll('.chip')].find(c => c.textContent === label); if (c) c.click(); }
  };
  pick('How many steps', 'One step');
  await new Promise(r => setTimeout(r, 250));
  pick('tall is the tallest', '10 cm');
  await new Promise(r => setTimeout(r, 250));
  pick('Is there a ramp', 'Portable ramp, ask staff');
  await new Promise(r => setTimeout(r, 250));
  pick('How wide is the opening', '80 cm');
  await new Promise(r => setTimeout(r, 300));
  document.getElementById('surveyBody').scrollTop = 300;
  document.getElementById('toast').hidden = true;
})()

